def fizzBuzz(n):
    result = []
    for i in range(1, n+1):
        # Check for divisibility by both 3 and 5 first
        if i % 15 == 0:
            result.append("FizzBuzz")
        # Only divisible by 3
        elif i % 3 == 0:
            result.append("Fizz")
        # Only divisible by 5
        elif i % 5 == 0:
            result.append("Buzz")
        # Not divisible by 3 or 5
        else:
            result.append(str(i))
    return result
